source("pre.R")
cat("--- enum with NA level\n")
e <- zutable(f = factor(c("a", NA, "b"), exclude = NULL), i = 1:3); print(format(schema(e))); print(as.data.frame(e[select = .(i, n = is.na(f))])); print(as.data.frame(e[select = .(c = count(f))])); print(try_(schema(f = enum(c("a", "b", NA))))); print(tryCatch({conform(e, schema(e)); "conform ok"}, error = function(e) conditionMessage(e)))
print(try_(as_zutable(as.data.frame(e), schema(f = not_null(enum(c("a", "b", NA))), i = int32))))
both(e[by = f, select = .(n = .N)]); print(as.data.frame(e[by = f, select = .(n = .N)]))
cat("--- invalid tz\n")
z <- suppressWarnings(try_(zutable(t = as.POSIXct("2020-01-01 12:00:00", tz = "Not/AZone")))); print(format(schema(z))); print(suppressWarnings(as.data.frame(z[select = .(s = cast(t, string), y = year(t))])))
cat("--- int32 -> int64 widening\n")
x <- zutable(i = zuint::int64(1:2), j = 1:2); try_(x[, i := j]); try_(x[, i := 7L]); try_(x$i <- 7L); try_(x[1, "i"] <- 7); print(try_(x[select = .(c = i == j)])); print(try_(x[select = .(c = i == 1L)])); print(try_(x[select = .(c = coalesce(i, 0L))])); print(try_(x[select = .(c = cast(j, int64))]))
cat("--- literal timestamp in DST gap / mixed set\n")
ny <- zutable(t = as.POSIXct("2021-03-14 07:30:00", tz = "UTC")); nyz <- ny[select = .(t = cast(t, timestamp("us", "America/New_York")))]; print(try_(nrow(nyz[t > "2021-03-14 02:30:00"]))); print(try_(nrow(nyz[t %in% c("2021-03-14 03:30:00", "2021-03-13")])))
tt <- zutable(t = as.POSIXct(c("2020-01-01 00:00:00", "2020-01-01 10:00:00", "2020-01-01 10:00:30"), tz = "UTC"))
print(nrow(tt[t %in% c("2020-01-01", "2020-01-01 10:00:00")])); print(nrow(tt[t == "2020-01-01" | t == "2020-01-01 10:00:00"])); print(nrow(tt[t %in% c("2020-01-01 10:00", "2020-01-01 10:00:30")])); print(nrow(tt[t %in% c("2020-01-01 10:00:30", "2020-01-01 10:00")]))
st <- zutable(s = c("2020-01-01 10:00:30", "2020-01-01 10:00", "2020-01-01")); r <- st[select = .(s, t = cast(s, timestamp))]; print(as.data.frame(r)); print(format(r$t, "%Y-%m-%d %H:%M:%S"))
for (v in st$s) print(format(zutable(s = v)[select = .(t = cast(s, timestamp))]$t, "%Y-%m-%d %H:%M:%S"))
cat("--- struct in over() default vs ref; struct ifelse\n")
s <- zutable(id = c(1L, 1L, 2L), st = data.frame(a = c(1L, 2L, 3L), b = c("x", "y", "z")))
a <- tryCatch(as.data.frame(s[select = .(id, w = over(first(st), by = id))]), error = function(e) conditionMessage(e)); b <- ref(tryCatch(as.data.frame(s[select = .(id, w = over(first(st), by = id))]), error = function(e) conditionMessage(e))); str(a); str(b)
print(try_(str(as.data.frame(s[select = .(c = case(id > 1L ~ st), i = ifelse(id > 1L, st, st), co = coalesce(st, st))]))))
